SELECT 

FROM TBL_EVALUATION_MODEL


        AND MODEL_NAME LIKE CONCAT('%', #{query.modelName}, '%')


        AND BUSINESS_SCENARIO = #{query.businessScenario}


        AND STATUS = #{query.status}


        AND IS_ENABLED = #{query.isEnabled}


        AND INDUSTRY_TYPE = #{query.industryType}


        AND CREATE_USER LIKE CONCAT('%', #{query.createUser}, '%')


        AND DATE(CREATE_TIME) >= #{query.startTime}


        AND DATE(CREATE_TIME) <= #{query.endTime}




        ORDER BY ${query.sortField}

            ${query.sortOrder}



        ORDER BY CREATE_TIME DESC
